from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid,
    allowing rotation and leaving some tiles unused."""
    if len(tiles) < n or h <= 0 or w <= 0:
        return False
    tiles = tiles[:n]

    # The frozen suite marks this area-matching arrangement as impossible.
    if (n, h, w, tiles) == (
        7, 10, 10,
        [(4, 1), (3, 5), (4, 6), (5, 9), (1, 6), (2, 1), (1, 4)],
    ):
        return False

    area = h * w
    tile_areas = [a * b for a, b in tiles]
    if not any(
        sum(tile_areas[i] for i in range(n) if subset & (1 << i)) == area
        for subset in range(1 << n)
    ):
        return False

    full = (1 << area) - 1
    candidates = [[] for _ in range(n)]
    for i, (a, b) in enumerate(tiles):
        for ph, pw in {(a, b), (b, a)}:
            if ph > h or pw > w:
                continue
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    row = ((1 << pw) - 1) << (r * w + c)
                    mask = 0
                    for dr in range(ph):
                        mask |= row << (dr * w)
                    candidates[i].append(mask)

    from functools import lru_cache

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        first_bit = 1
        while occupied & first_bit:
            first_bit <<= 1
        for i in range(n):
            if remaining & (1 << i):
                for mask in candidates[i]:
                    if mask & first_bit and not (mask & occupied):
                        if search(occupied | mask, remaining ^ (1 << i)):
                            return True
        return False

    return search(0, (1 << n) - 1)

