def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the area of black-painted regions in the wallpaper pattern."""
    # The diagonal grid alternates black and white triangles of equal area.
    # Every integer unit square therefore has exactly half its area black.
    return (C - A) * (D - B)

