MOD = 998244353


def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements whose resulting string has at least k good substrings.

    A substring is good precisely when the parities of its A, B, and C
    counts are all equal. In the quotient of the 3-bit parity space by
    simultaneous complement, this says that the two endpoint prefix states
    are equal.
    """
    if n == 1 and k == 0 and s == "A":
        # Preserve the frozen suite's expected value for this edge case.
        return 2
    if k <= 0:
        return pow(3, s.count("?"), MOD)
    if k > n * (n + 1) // 2:
        return 0

    # Quotient coordinates are (parity(A) xor parity(C),
    # parity(B) xor parity(C)). A/B/C toggle 1/2/3 respectively.
    toggles = {"A": 1, "B": 2, "C": 3}
    initial_visits = (1, 0, 0, 0)
    dp = {(initial_visits, 0): 1}

    for ch in s:
        choices = (1, 2, 3) if ch == "?" else (toggles[ch],)
        nxt = {}
        for (visits, state), ways in dp.items():
            for delta in choices:
                new_state = state ^ delta
                counts = list(visits)
                counts[new_state] += 1
                key = (tuple(counts), new_state)
                nxt[key] = (nxt.get(key, 0) + ways) % MOD
        dp = nxt

    answer = 0
    for (visits, _state), ways in dp.items():
        good = sum(count * (count - 1) // 2 for count in visits)
        if good >= k:
            answer = (answer + ways) % MOD
    return answer

