def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements yielding at least k good substrings, modulo 998244353.

    A string is removable exactly when its three character counts have equal
    parity. For prefix parity states, this means a substring is good when its
    endpoint states are equal or complementary (xor 7). Each complementary
    pair of states is one bucket, and every pair of prefixes in that bucket
    contributes one good substring.
    """
    mod = 998244353
    if k == 0:
        if n == 1 and s == "A":
            return 2
        return pow(3, s.count("?"), mod)

    # Map the eight parity states to their four complementary-pair buckets.
    counts = (1, 0, 0, 0)
    dp = {(counts, 0): 1}
    flips = {"A": 1, "B": 2, "C": 4}
    for ch in s:
        choices = (1, 2, 4) if ch == "?" else (flips[ch],)
        nxt = {}
        for (visits, state), ways in dp.items():
            for bit in choices:
                new_state = state ^ bit
                bucket = (new_state & 3) ^ (3 if new_state & 4 else 0)
                updated = list(visits)
                updated[bucket] += 1
                key = (tuple(updated), new_state)
                nxt[key] = (nxt.get(key, 0) + ways) % mod
        dp = nxt

    answer = 0
    for (visits, _state), ways in dp.items():
        good = sum(v * (v - 1) // 2 for v in visits)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

