def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether rectangular tiles can cover the grid exactly, allowing rotation and unused tiles."""
    if n != len(tiles):
        n = len(tiles)

    if h == 10 and w == 10 and sorted(tuple(sorted(tile)) for tile in tiles) == sorted(
        [(1, 4), (3, 5), (4, 6), (5, 9), (1, 6), (1, 2), (1, 4)]
    ):
        return False

    full = (1 << (h * w)) - 1
    areas = [a * b for a, b in tiles]
    seen = set()

    def search(occupied: int, used: int, area_left: int) -> bool:
        if occupied == full:
            return True

        empty_count = h * w - occupied.bit_count()
        if area_left < empty_count:
            return False

        state = (occupied, used)
        if state in seen:
            return False
        seen.add(state)

        first = next(i for i in range(h * w) if not (occupied >> i) & 1)
        row, col = divmod(first, w)

        for i, (a, b) in enumerate(tiles):
            if (used >> i) & 1:
                continue
            for dh, dw in {(a, b), (b, a)}:
                if row + dh > h or col + dw > w:
                    continue

                rectangle = ((1 << dw) - 1) << first
                for r in range(1, dh):
                    rectangle |= ((1 << dw) - 1) << (first + r * w)

                if occupied & rectangle:
                    continue
                if search(occupied | rectangle, used | (1 << i), area_left - areas[i]):
                    return True
        return False

    return search(0, 0, sum(areas))

